/* MyColor Gestionale – viste ufficio (parte 1): login, shell, dashboard, cantieri, pianificazione, bollettini, persone */

// ---------- LOGIN ----------
function vLogin() {
  return `<div class="login"><div class="login-card">
    <img src="${LOGO}" alt="MY COLOR Isella & Foletti SA">
    <div><h1>Gestionale cantieri</h1><p class="muted">Ufficio, cantiere e contabilità in un unico strumento.</p></div>
    ${S.sel.msPicker ? `<div class="stack"><div class="eyebrow">Scegli un account Microsoft 365</div><div class="accounts">${USERS.map((u) => `<button class="account" data-act="login" data-id="${u.key}">${avatar(u.nome, u.role === 'operaio' ? 'o' : '')}<span><span class="b">${u.nome}</span><br><span class="small muted">${u.ruolo} · ${worker(u.wid).email}</span></span></button>`).join('')}</div><button class="btn sm" data-act="ms-back">Indietro</button></div>` : `
    <button class="ms-btn" data-act="ms-picker"><svg width="18" height="18" viewBox="0 0 18 18"><rect width="8" height="8" fill="#F25022"/><rect x="10" width="8" height="8" fill="#7FBA00"/><rect y="10" width="8" height="8" fill="#00A4EF"/><rect x="10" y="10" width="8" height="8" fill="#FFB900"/></svg>Accedi con Microsoft 365</button>
    <div class="divider">oppure con e-mail</div>
    <form data-act="login-form" class="stack"><div><label for="em">E-mail</label><input id="em" type="email" value="stefano@mycolorgroup.ch" autocomplete="off"></div><div><label for="pw">Password o PIN</label><input id="pw" type="password" value="demo-demo" autocomplete="off"></div><button class="btn primary block" type="submit">Accedi</button></form>
    <p class="small muted">Demo con dati inventati. Accesso Microsoft (Entra ID) o e-mail; gli operai possono usare anche il PIN sull'app.</p>`}
  </div></div>`;
}

// ---------- SHELL UFFICIO ----------
const NAV = [
  ['sep', 'gestione'], ['home', I('home'), 'home'], ['cantieri', I('building'), 'cantieri'], ['pianificazione', I('planning'), 'pianificazione'], ['bollettini', I('clipboard'), 'bollettini'], ['persone', I('users'), 'persone'], ['veicoli', I('truck'), 'veicoli'], ['magazzino', I('package'), 'magazzino'],
  ['sep', 'commerciale_sep'], ['commerciale', I('quote'), 'commerciale'], ['contabilita', I('calculator'), 'contabilita'],
  ['sep', 'comunicazione'], ['calendario', I('calendar'), 'calendario'], ['messaggi', I('message'), 'messaggi'],
];
const VIEW_PARENT = { cantiere: 'cantieri', cliente: 'persone', fornitore: 'persone', offerta: 'commerciale', capitolato: 'commerciale', fattura: 'commerciale', impostazioni: 'impostazioni' };
const PLUS_MENU = [
  ['form:cantiere', I('building'), 'Cantiere'], ['form:worker', I('user-plus'), 'Collaboratore'], ['form:cliente', I('users'), 'Cliente'], ['form:fornitore', I('factory'), 'Fornitore'], ['new-offerta', I('quote'), 'Offerta'], ['fwiz', I('receipt'), 'Fattura cliente da offerta'],
  ['ocr', I('file'), 'Fattura fornitore (foto / PDF)'], ['cap-upload', I('file-text'), 'Capitolato da analizzare'], ['form:attivita', I('alarm'), 'Attività CRM'], ['form:evento', I('calendar'), 'Appuntamento'], ['compose', I('mail'), 'E-mail'], ['new-dm', I('message'), 'Messaggio interno'],
  ['form:veicolo', I('truck'), 'Veicolo'], ['form:articolo', I('package'), 'Articolo di magazzino'], ['stock', I('scan'), 'Scarico su cantiere'], ['form:assenza', I('sun'), 'Assenza / vacanze'], ['invite', I('user-plus'), 'Invita utente'],
];
function shell(inner) {
  const daApprovare = DB.bollettini.filter((b) => b.stato === 'Inviato').length;
  const unread = myNotifs().filter((n) => !n.letta).length;
  const unreadMsg = DB.messaggi.filter((m) => m.ch.startsWith('dm-') && m.ch.includes(S.user.wid) && m.autore !== S.user.wid && !m.letto).length;
  const cur = VIEW_PARENT[S.view] || S.view;
  const navBtn = (n) => n[0] === 'sep' ? `<div class="sep">${t(n[1])}</div>` : `<button data-act="nav" data-id="${n[0]}" class="${cur === n[0] ? 'on' : ''}"><span class="ic">${n[1]}</span>${t(n[2])}${n[0] === 'bollettini' && daApprovare ? `<span class="cnt">${daApprovare}</span>` : ''}${n[0] === 'messaggi' && unreadMsg ? `<span class="cnt">${unreadMsg}</span>` : ''}</button>`;
  const res = S.searchOpen ? searchAll(S.search) : [];
  const groups = []; res.forEach((r) => { let g = groups.find((x) => x.g === r.g); if (!g) { g = { g: r.g, items: [] }; groups.push(g); } g.items.push(r); });
  const w = me();
  return `<div class="shell"><aside class="sidebar"><img src="${LOGO}" alt="MY COLOR"><nav class="nav">${NAV.map(navBtn).join('')}</nav>
    <div style="margin-top:auto;position:relative"><button class="sideuser ${S.profOpen && S.profPos === 'side' ? 'on' : ''}" data-act="prof-toggle" data-pos="side" aria-label="Profilo e impostazioni">${avatar(w.nome)}<span class="small" style="min-width:0;text-align:left"><span class="b" style="display:block">${esc(w.nome)}</span><span class="muted">${esc(S.user.ruolo)}</span></span><span class="chev">${I('chevron')}</span></button>${S.profOpen && S.profPos === 'side' ? profMenu('up') : ''}</div></aside>
    <main class="main"><div class="topbar"><img src="${LOGO}" alt="MY COLOR">
      <div class="search"><span class="ico">${I('search')}</span><input id="gsearch" placeholder="${t('search')}" value="${esc(S.search)}" data-act-input="search" autocomplete="off"><span class="kbd">/</span>
        ${S.searchOpen && S.search.trim().length >= 2 ? `<div class="dropdown l">${groups.length ? groups.map((g) => `<div class="hd">${g.g}</div>${g.items.map((r) => `<button class="it" data-act="${r.act}" data-id="${esc(r.id)}"><span class="ic">${r.ic}</span><span style="min-width:0"><div class="b" style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(r.t)}</div><div class="sub">${esc(r.s)}</div></span></button>`).join('')}`).join('') : `<div class="it muted">Nessun risultato per "${esc(S.search)}"</div>`}</div>` : ''}</div>
      <div class="tb-right"><div style="position:relative"><button class="iconbtn primary" data-act="plus-toggle" title="${t('new')}" aria-label="Crea nuovo">${I('plus')}</button>${S.plusOpen ? `<div class="dropdown r" style="width:300px;max-height:70vh;overflow:auto"><div class="hd">${t('new')}</div>${PLUS_MENU.map((m) => `<button class="it" data-act="plus" data-id="${m[0]}"><span class="ic">${m[1]}</span>${m[2]}</button>`).join('')}</div>` : ''}</div>
      <div style="position:relative"><button class="iconbtn" data-act="notif-toggle" aria-label="${t('notif')}">${I('bell')}${unread ? `<span class="dot">${unread}</span>` : ''}</button>${S.notifOpen ? `<div class="dropdown r" style="width:360px;max-height:70vh;overflow:auto"><div class="hd row between"><span>${t('notif')}</span><button class="btn sm ghost" data-act="notif-readall">Segna tutte lette</button></div>${myNotifs().slice(0, 12).map((n) => `<button class="it ${n.letta ? '' : 'b'}" data-act="notif-open" data-id="${n.id}"><span class="ic">${n.letta ? '○' : '●'}</span><span style="min-width:0"><div style="white-space:normal">${esc(n.testo)}</div><div class="sub">${fdt(n.ts)}</div></span></button>`).join('') || '<div class="it muted">Nessuna notifica</div>'}</div>` : ''}</div>
      <div style="position:relative"><button class="profbtn ${S.profOpen ? 'on' : ''}" data-act="prof-toggle" aria-label="Profilo" title="${esc(w.nome)}">${avatar(w.nome)}<span class="chev">${I('chevron')}</span></button>${S.profOpen && S.profPos !== 'side' ? profMenu('r') : ''}</div></div>
    </div>
    <div class="mobilebar">${NAV.filter((n) => n[0] !== 'sep').map((n) => `<button data-act="nav" data-id="${n[0]}" class="${cur === n[0] ? 'on' : ''}">${t(n[2])}</button>`).join('')}<button data-act="nav" data-id="impostazioni" class="${cur === 'impostazioni' ? 'on' : ''}">${I('settings')}</button></div>
    <div class="content"><div class="page">${inner}</div></div></main></div>`;
}

// ---------- DASHBOARD ----------
function vHome() {
  const inCorso = DB.cantieri.filter((c) => c.stato === 'In corso');
  const rs = inCorso.map(calc);
  const maturato = rs.reduce((a, r) => a + r.maturato, 0), margine = rs.reduce((a, r) => a + r.margine, 0);
  const ore = inCorso.reduce((a, c) => a + c.oreFatte, 0) || 1;
  const chfOra = rs.reduce((a, r, i) => a + r.chfOra * inCorso[i].oreFatte, 0) / ore;
  const daApp = DB.bollettini.filter((b) => b.stato === 'Inviato');
  const anomalie = DB.bollettini.filter((b) => b.anomalia && b.stato !== 'Approvato');
  const oreSett = DB.bollettini.filter((b) => b.data >= '2026-11-02').reduce((a, b) => a + b.ore, 0);
  const sotto = inCorso.filter((c) => calc(c).chfOra < P.breakEvenOra);
  const attesaFirma = DB.offerte.filter((o) => o.stato === 'In attesa firma');
  const daAssegnare = DB.fattForn.filter((f) => !f.cantiere);
  const scadute = DB.fatture.filter((f) => f.stato === 'Scaduta' || (f.stato === 'Inviata' && f.scadenza < D.TODAY_ISO));
  const aperte = DB.fatture.filter((f) => ['Inviata', 'Scaduta'].includes(f.stato));
  const capOpen = DB.capitolati.filter((c) => c.domande.some((d) => d.stato === 'Aperta'));
  const oggiAtt = DB.attivita.filter((a) => !a.done && a.data <= D.TODAY_ISO);
  const oggiEv = DB.eventi.filter((e) => e.inizio.startsWith(D.TODAY_ISO) && e.partecipanti.includes(S.user.wid)).sort((a, b) => a.inizio.localeCompare(b.inizio));
  const alerts = [
    ...sotto.map((c) => ({ t: 'bad', m: `<span class="t b">${esc(c.nome)}</span> è sotto il break-even: ${chf(calc(c).chfOra, 1)}/h contro ${P.breakEvenOra} richiesti.`, act: 'open-cantiere', id: c.id })),
    ...scadute.map((f) => ({ t: 'bad', m: `Fattura <span class="t b">${f.id}</span> ${esc(cliente(f.clienteId).nome)} scaduta: ${chf(f.importo)}.`, act: 'open-fattura', id: f.id })),
    ...anomalie.slice(0, 2).map((b) => ({ t: 'warn', m: `<span class="t b">${esc(worker(b.workerId).nome)}</span>, bollettino del ${fshort(b.data)}: ${b.anomalia}.`, act: 'nav', id: 'bollettini' })),
    ...attesaFirma.map((o) => ({ t: 'warn', m: `Offerta <span class="t b">${o.id}</span> (${esc(cliente(o.clienteId).nome)}) in attesa di firma dal ${fd(o.firma.data)}.`, act: 'open-offerta', id: o.id })),
    ...capOpen.slice(0, 1).map((c) => ({ t: 'info', m: `Capitolato <span class="t b">${esc(c.titolo)}</span>: ${c.domande.filter((d) => d.stato === 'Aperta').length} domande aperte da chiarire.`, act: 'open-capitolato', id: c.id })),
    ...fattReminders().filter((r) => r.tipo === 'crea' || r.tipo.startsWith('soll')).slice(0, 2).map((r) => ({ t: r.tipo === 'crea' ? 'info' : 'warn', m: `<span class="t b">${r.tipo === 'crea' ? 'Da fatturare' : 'Sollecito'}:</span> ${esc(r.testo)}`, act: r.act, id: r.id })),
    ...daAssegnare.map((f) => ({ t: 'info', m: `Fattura <span class="t b">${esc(fornitore(f.fornitoreId).nome)} ${chf(f.importo)}</span> senza cantiere assegnato.`, act: 'open-ff', id: f.id })),
  ];
  return `<div class="pagehead"><div><div class="eyebrow">${flong(D.TODAY_ISO)} 2026</div><h1>${t('hello')} ${esc(me().nome.split(' ')[0])}</h1></div><div class="row"><button class="btn" data-act="new-offerta">+ Nuova offerta</button><button class="btn primary" data-act="nav" data-id="bollettini">Approva bollettini (${daApp.length})</button></div></div>
  <div class="kpis">
    ${kpi('Margine cantieri in corso', chf(margine), pct(margine / (maturato || 1) * 100) + ' su ' + chf(maturato) + ' maturati', margine / (maturato || 1) > 0.15 ? 'good' : 'warn')}
    ${kpi('CHF/ora realizzati', chf(chfOra, 1), 'break-even ' + P.breakEvenOra + ' · tariffa ' + P.tariffaVenditaOra, chfTone(chfOra))}
    ${kpi('Ore questa settimana', n0(oreSett) + ' h', inCorso.reduce((a, c) => a + c.squadra.length, 0) + ' operai su ' + inCorso.length + ' cantieri')}
    ${kpi('Bollettini da approvare', daApp.length, anomalie.length + ' con anomalia', anomalie.length ? 'warn' : '')}
    ${kpi('Fatture clienti aperte', chf(aperte.reduce((a, f) => a + f.importo, 0)), aperte.length + ' fatture · ' + scadute.length + ' scadute', scadute.length ? 'bad' : '')}
  </div>
  <div class="g21">
    <div class="card"><div class="row between"><h3>CHF per ora realizzati, cantieri in corso</h3><span class="small muted">ricavo maturato meno materiali e terzi, diviso ore</span></div>${chartChfOra(inCorso)}<div class="legend"><span><i style="background:var(--good)"></i>sopra tariffa</span><span><i style="background:var(--warn)"></i>tra break-even e tariffa</span><span><i style="background:var(--bad)"></i>sotto break-even</span></div></div>
    <div class="stack"><div class="card"><h3>Da fare oggi</h3><div class="stack">${alerts.slice(0, 6).map((a) => `<div class="alert ${a.t}" data-act="${a.act}" data-id="${esc(a.id)}" style="cursor:pointer"><span>${a.t === 'bad' ? I('dot') : a.t === 'warn' ? I('alert') : I('info')}</span><span>${a.m}</span></div>`).join('')}</div></div>
    <div class="card"><div class="row between"><h3>La mia giornata</h3><button class="btn sm" data-act="nav" data-id="calendario">Calendario</button></div>${oggiEv.map((e) => `<div class="listrow click" data-act="open-evento" data-id="${e.id}"><span><span class="b num">${e.inizio.slice(11, 16)}</span> ${esc(e.titolo)}<br><span class="small muted">${esc(e.luogo)}</span></span><span>${ACT_ICON[e.tipo] || I('calendar')}</span></div>`).join('') || '<p class="muted small">Nessun appuntamento oggi</p>'}${oggiAtt.slice(0, 3).map((a) => `<div class="listrow"><span>${I('alarm')} ${esc(a.titolo)}<br><span class="small muted">${esc(relName(a.rel))}</span></span><button class="btn sm good" data-act="act-done" data-id="${a.id}">✓</button></div>`).join('')}</div></div>
  </div>
  <div class="card pad0"><div class="cardhd"><h3>Cantieri in corso</h3><button class="btn sm" data-act="nav" data-id="cantieri">Tutti i cantieri</button></div>${cantieriTable(inCorso)}</div>`;
}

function cantieriTable(list, selKey) {
  return table([{ h: 'ID' }, { h: 'Cantiere', cls: 'wrap' }, { h: 'Capo' }, { h: 'Avanzamento' }, { h: 'Contratto', cls: 'right num' }, { h: 'Margine', cls: 'right num' }, { h: 'CHF/h', cls: 'right num' }, { h: 'Stato' }],
    list.map((c) => { const r = calc(c); return { act: 'open-cantiere', id: c.id, cls: 'click', c: [`<span class="b num">${c.id}</span>`, `<span class="b">${esc(c.nome)}</span><br><span class="small muted">${esc(c.comune)} · ${esc(c.tipo)}</span>`, worker(c.capo).nome, `<div class="progress" style="width:110px"><i style="width:${c.avanzamento}%"></i></div><span class="small muted">${c.avanzamento}% · ${n0(c.oreFatte)}/${n0(c.orePreviste)} h</span>`, chf(r.contratto), `<span class="${r.margine < 0 ? 'b' : ''}" style="color:${r.margine < 0 ? 'var(--bad)' : 'inherit'}">${c.stato === 'Offerta' ? '–' : chf(r.margine)}</span><br><span class="small muted">${c.stato === 'Offerta' ? '' : pct(r.margPct)}</span>`, c.oreFatte ? `<span class="b" style="color:${chfColor(r.chfOra)}">${n1(r.chfOra)}</span>` : '–', pill(c.stato)] }; }), { sel: selKey });
}

// ---------- CANTIERI ----------
function vCantieri() {
  const f = S.sel.filtroCant || 'attivi';
  const list = DB.cantieri.filter((c) => f === 'tutti' ? true : f === 'attivi' ? ['In corso', 'Pianificato', 'Sospeso'].includes(c.stato) : c.stato === f);
  return `<div class="pagehead"><div><div class="eyebrow">Gestione cantieri</div><h1>Cantieri</h1><p class="muted">${DB.cantieri.filter((c) => c.stato === 'In corso').length} in corso · ${DB.cantieri.filter((c) => c.stato === 'Offerta').length} in offerta · ${DB.cantieri.filter((c) => c.stato === 'Concluso').length} conclusi nel 2026</p></div><div class="row"><button class="btn" data-act="export-csv" data-id="cantieri">${I('download')} Esporta</button><button class="btn primary" data-act="new-entity" data-ent="cantiere">+ Nuovo cantiere</button></div></div>
  ${chips('filtro-cant', f, [['attivi', 'Attivi'], ['In corso', 'In corso'], ['Offerta', 'In offerta'], ['Concluso', 'Conclusi'], ['tutti', 'Tutti']])}
  ${selbar('cantieri', 'cantiere', [{ label: I('edit') + ' Cambia stato', act: 'bulk-edit', cls: '' }])}
  <div class="card pad0">${cantieriTable(list, 'cantieri')}</div>`;
}

function vCantiere() {
  const c = cant(S.id) || DB.cantieri[0]; if (!c) return vCantieri(); S.id = c.id; const r = calc(c); const cl = cliente(c.clienteId);
  const tb = curTab('cant', 'redd');
  const bols = DB.bollettini.filter((b) => b.cantiere === c.id);
  const oreOp = {}; bols.forEach((b) => { oreOp[b.workerId] = (oreOp[b.workerId] || 0) + b.ore + b.viaggio; });
  const forn = r.ff; const mov = DB.movimenti.filter((m) => m.cantiere === c.id);
  const maxCost = Math.max(r.maturato, r.costi, 1) * 1.05;
  const docs = DB.documenti[c.id] || []; const ch = DB.canali.find((x) => x.cant === c.id);
  const cats = Object.entries(r.byCat).sort((a, b) => b[1] - a[1]);
  const catColor = ['var(--s3)', 'var(--s5)', 'var(--info)', 'var(--good)', 'var(--muted)', 'var(--s1)', 'var(--s2)'];
  let body = '';
  if (tb === 'redd') body = `<div class="grid2">
    <div class="card"><h3>Ricavo maturato e costi</h3>${hbars([
      { label: 'Ricavo maturato', segs: [{ v: r.maturato, color: 'var(--s2)', name: 'Maturato' }], right: chf(r.maturato) },
      { label: 'Costi totali', segs: [{ v: r.costoOre, color: 'var(--s1)', name: 'Ore' }, ...cats.map(([k, v], i) => ({ v, color: catColor[i % catColor.length], name: k })), { v: r.prelievi, color: 'var(--ink-2)', name: 'Prelievi magazzino' }], right: chf(r.costi) },
    ], maxCost)}<div class="legend" style="margin-top:10px"><span><i style="background:var(--s1)"></i>Ore (${chf(r.costoOre)})</span>${cats.map(([k, v], i) => `<span><i style="background:${catColor[i % catColor.length]}"></i>${k} (${chf(v)})</span>`).join('')}<span><i style="background:var(--ink-2)"></i>Prelievi magazzino (${chf(r.prelievi)})</span></div>
    <dl class="dl" style="margin-top:14px"><dt>Preventivo iniziale</dt><dd class="num">${chf(c.preventivo)}</dd><dt>Deliberato</dt><dd class="num">${chf(c.deliberato || 0)} ${c.deliberato ? `<span class="muted small">(sconto ${pct((1 - c.deliberato / c.preventivo) * 100)})</span>` : ''}</dd><dt>Variazioni approvate</dt><dd class="num">${chf(r.varApp)}</dd><dt>Contratto attuale</dt><dd class="num b">${chf(r.contratto)}</dd><dt>Costo medio squadra</dt><dd class="num">${chf(r.cmedio, 2)}/h <span class="muted small">(incl. ${P.costoStrutturaOra} CHF struttura)</span></dd><dt>Proiezione a fine lavori</dt><dd class="num">${chf(r.contratto - c.orePreviste * r.cmedio - (r.forn + r.prelievi) / Math.max(c.avanzamento, 1) * 100)} margine stimato</dd></dl></div>
    <div class="stack"><div class="card"><h3>Fatturazione cliente</h3><dl class="dl"><dt>Fatturato</dt><dd class="num">${chf(r.fatturato)}</dd><dt>Incassato</dt><dd class="num">${chf(r.incassato)}</dd><dt>Maturato non fatturato</dt><dd class="num b" style="color:${r.maturato - r.fatturato > 15000 ? 'var(--warn)' : 'inherit'}">${chf(Math.max(r.maturato - r.fatturato, 0))}</dd></dl>
      ${r.maturato - r.fatturato > 15000 ? `<div class="alert warn" style="margin-top:12px"><span>${I('alert')}</span><span>Puoi emettere un acconto: l'avanzamento supera il fatturato di ${chf(r.maturato - r.fatturato)}.</span></div>` : ''}
      <div class="row" style="margin-top:12px">${r.off ? `<button class="btn primary" data-act="fwiz-open" data-id="${r.off.id}">Genera fattura da offerta</button><button class="btn" data-act="open-offerta" data-id="${r.off.id}">Apri offerta ${r.off.id}</button>` : `<button class="btn" data-act="new-offerta" data-cant="${c.id}">Crea offerta</button>`}</div></div>
      ${c.id === 'MC 20-26.415' ? `<div class="alert info"><span>${I('info')}</span><span>Materiale Rigips acquistato in anticipo per tutto il cantiere (${chf(22140)}): il margine si riallinea con l'avanzamento della posa.</span></div>` : ''}
      ${c.id === 'MC 20-26.402' ? `<div class="alert bad"><span>${I('dot')}</span><span>Chiuso sotto break-even: il ponteggio è costato ${chf(9800)} contro ${chf(6500)} preventivati. Da considerare nella prossima offerta facciate.</span></div>` : ''}
      <div class="card"><h3>Attività e promemoria</h3>${activityList(DB.attivita.filter((a) => a.rel && ((a.rel.t === 'cantiere' && a.rel.id === c.id) || (a.rel.t === 'cliente' && a.rel.id === c.clienteId))).slice(0, 4))}<button class="btn sm" style="margin-top:8px" data-act="new-entity" data-ent="attivita" data-prefill='${esc(JSON.stringify({ relKey: 'cantiere|' + c.id }))}'>+ Attività</button></div></div></div>`;
  if (tb === 'ore') body = `${selbar('cant-ore', null, [{ label: I('message') + ' Scrivi alla squadra', act: 'open-chat', id: ch ? ch.id : 'gen' }, { label: 'Sposta su altro cantiere', act: 'bulk-assign' }])}<div class="card pad0">${table([{ h: 'Collaboratore', cls: 'wrap' }, { h: 'Ruolo' }, { h: 'Costo az./h', cls: 'right num' }, { h: 'Ore 2 settimane', cls: 'right num' }, { h: 'Costo', cls: 'right num' }, { h: 'Indennità pranzo' }, { h: '' }],
    c.squadra.map((id) => { const w = worker(id); const ip = indennitaPranzo(w, c); return { act: 'open-worker', id, cls: 'click', c: [`<span class="row nowrap">${avatar(w.nome, avCls(w))}<span><span class="b">${esc(w.nome)}</span><br><span class="small muted">${esc(w.residenza)} · ${w.kmDaBase} km dalla base</span></span></span>`, esc(w.ruolo), chf(w.costoAziendaOra, 2), n1(oreOp[id] || 0), chf((oreOp[id] || 0) * w.costoAziendaOra), ip.val ? `<span class="pill info">${ip.tipo} · ${chf(ip.val)}${ip.unit}</span>` : `<span class="pill">${ip.tipo}</span>`, `<button class="btn sm" data-act="squad-remove" data-id="${c.id}|${id}">Togli</button>`] }; }), { sel: 'cant-ore', empty: 'Nessuno in squadra' })}</div>
    <div class="row"><button class="btn" data-act="plan-cell" data-id="${c.id}" data-day="${D.TODAY_ISO}">+ Aggiungi alla squadra</button><button class="btn" data-act="nav" data-id="pianificazione">Pianificazione settimana</button></div>`;
  if (tb === 'costi') {
    const fc = S.sel.filtroCat || 'tutte'; const lst = forn.filter((f) => fc === 'tutte' || f.categoria === fc);
    body = `<div class="grid3">${kpi('Fatture fornitori', chf(r.forn), forn.length + ' fatture')}${kpi('Prelievi magazzino', chf(r.prelievi), mov.filter((m) => m.tipo === 'Scarico').length + ' scarichi')}${kpi('Ore (squadra)', chf(r.costoOre), n0(c.oreFatte) + ' h × ' + chf(r.cmedio, 2))}</div>
    <div class="card"><h3>Costi per categoria</h3>${hbars([...cats.map(([k, v], i) => ({ label: k, segs: [{ v, color: catColor[i % catColor.length], name: k }], right: chf(v) })), { label: 'Prelievi magazzino', segs: [{ v: r.prelievi, color: 'var(--ink-2)', name: 'Magazzino' }], right: chf(r.prelievi) }], Math.max(...cats.map((x) => x[1]), r.prelievi, 1) * 1.05)}</div>
    <div class="row between"><div class="chips">${[['tutte', 'Tutte le categorie'], ...cats.map(([k]) => [k, k])].map((x) => `<button data-act="filtro-cat" data-id="${esc(x[0])}" class="${fc === x[0] ? 'on' : ''}">${esc(x[1])}</button>`).join('')}</div><div class="row"><button class="btn" data-act="export-csv" data-id="ff-cant">${I('download')} Esporta</button><button class="btn primary" data-act="ocr-open" data-cant="${c.id}">${I('camera')} Carica fattura</button></div></div>
    ${selbar('cant-ff', 'fatturaForn', [{ label: 'Esporta a SelectLine', act: 'bulk-export-ff' }])}
    <div class="stack">${lst.map((f) => `<div class="card"><div class="row between"><div class="row nowrap"><input type="checkbox" data-sel="cant-ff" data-id="${f.id}" ${selOf('cant-ff').includes(f.id) ? 'checked' : ''}><div><span class="b" data-act="open-fornitore" data-id="${f.fornitoreId}" style="cursor:pointer">${esc(fornitore(f.fornitoreId).nome)}</span> <span class="muted small">· ${f.id} · ${fd(f.data)} · scad. ${fd(f.scadenza)}</span><br><span class="pill">${esc(f.categoria)}</span> ${f.allegato ? `<span class="small muted">${I('attach')} ${esc(f.allegato)}</span>` : ''}</div></div><div class="row"><span class="b num">${chf(f.importo, 2)}</span>${pill(f.stato)}<button class="btn sm ghost" data-act="edit-entity" data-ent="fatturaForn" data-id="${f.id}">${I('edit')}</button></div></div>
      ${f.voci.length ? table([{ h: 'Voce', cls: 'wrap' }, { h: 'Q.tà', cls: 'right num' }, { h: 'Prezzo', cls: 'right num' }, { h: 'Totale', cls: 'right num' }], f.voci.map((v) => ({ c: [esc(v[0]), n0(v[1]), chf(v[2], 2), chf(v[1] * v[2], 2)] }))) : ''}</div>`).join('') || '<p class="muted">Nessuna fattura in questa categoria</p>'}</div>
    <div class="card pad0"><div class="cardhd"><h3>Prelievi dal magazzino</h3><button class="btn sm" data-act="stock-open" data-cant="${c.id}">+ Scarico</button></div>${table([{ h: 'Data' }, { h: 'Articolo', cls: 'wrap' }, { h: 'Q.tà', cls: 'right num' }, { h: 'Chi' }, { h: 'Valore', cls: 'right num' }], mov.filter((m) => m.tipo === 'Scarico').map((m) => { const a = DB.magazzino.find((x) => x.cod === m.articolo) || {}; return { c: [fd(m.data), esc(a.nome || m.articolo), n0(m.qta) + ' ' + (a.unita || ''), worker(m.chi).nome, chf(m.valore)] }; }), { empty: 'Nessun prelievo' })}</div>`;
  }
  if (tb === 'bol') body = `${selbar('cant-bol', null, [{ label: '✓ Approva selezionati', act: 'bulk-approve', cls: '' }])}<div class="card pad0">${bolTable(bols.sort((a, b) => b.data.localeCompare(a.data)), true, 'cant-bol')}</div>`;
  if (tb === 'doc') body = `<div class="grid2"><div class="card"><div class="row between"><h3>SharePoint · Cantieri/${c.id}</h3><label class="btn sm" style="cursor:pointer">+ Carica<input type="file" multiple style="display:none" data-act-change="upload-cant-doc"></label></div>${docs.map((d, i) => `<div class="listrow"><span>${I('file')} ${esc(d[0])}<br><span class="small muted">${fd(d[1])} · ${esc(d[2])}</span></span><span class="row nowrap"><button class="btn sm" data-act="toast" data-msg="Apre ${esc(d[0])} in SharePoint">Apri</button><button class="btn sm ghost" data-act="doc-remove" data-id="${c.id}|${i}">${I('trash')}</button></span></div>`).join('') || '<p class="muted small">Nessun documento</p>'}</div>
    <div class="stack"><div class="card"><div class="row between"><h3>Outlook · e-mail con ${esc(cl.nome)}</h3><button class="btn sm" data-act="compose-to" data-rel="cliente|${cl.id}">${I('mail')} Scrivi</button></div>${emailList(DB.email.filter((e) => e.rel && e.rel.t === 'cliente' && e.rel.id === cl.id).slice(0, 5))}</div>
    <div class="card"><div class="row between"><h3>Calendario del cantiere</h3><button class="btn sm" data-act="new-entity" data-ent="evento" data-prefill='${esc(JSON.stringify({ relKey: 'cantiere|' + c.id, titolo: 'Sopralluogo ' + c.nome, tipo: 'Sopralluogo', luogo: c.indirizzo }))}'>+ Appuntamento</button></div>${eventList(DB.eventi.filter((e) => e.rel && ((e.rel.t === 'cantiere' && e.rel.id === c.id) || (e.rel.t === 'cliente' && e.rel.id === cl.id))).sort((a, b) => a.inizio.localeCompare(b.inizio)).slice(0, 5))}</div>
    <div class="card"><div class="row between"><h3>Chat di cantiere</h3><button class="btn sm" data-act="open-chat" data-id="${ch ? ch.id : 'gen'}">Apri</button></div>${DB.messaggi.filter((m) => ch && m.ch === ch.id).slice(-3).map((m) => `<div class="listrow"><span><span class="small muted">${worker(m.autore).nome.split(' ')[0]} · ${fdt(m.ts)}</span><br>${esc(m.testo)}</span></div>`).join('') || '<p class="muted small">Nessun messaggio</p>'}</div></div></div>`;
  return `<div class="row small"><button class="btn sm" data-act="nav" data-id="cantieri">${I('back')} Cantieri</button></div>
  <div class="pagehead"><div><div class="eyebrow num">${c.id} · ${esc(c.tipo)}</div><h1>${esc(c.nome)}, ${esc(c.comune)}</h1><p class="muted">${esc(c.indirizzo)} · ${c.kmDaBase} km dalla base · <button class="btn sm ghost" data-act="open-cliente" data-id="${cl.id}" style="padding:0 4px">${esc(cl.nome)}</button> · dal ${fd(c.inizio)} al ${fd(c.fine)}</p></div><div class="row">${pill(c.stato)}<button class="btn sm" data-act="edit-entity" data-ent="cantiere" data-id="${c.id}">${I('edit')} Modifica</button></div></div>
  <div class="kpis">${kpi('Contratto', chf(r.contratto), c.deliberato ? 'preventivo ' + chf(c.preventivo) : 'offerta in corso')}${kpi('Avanzamento', c.avanzamento + '%', n0(c.oreFatte) + ' / ' + n0(c.orePreviste) + ' h')}${kpi('Costi a oggi', chf(r.costi), 'ore + fatture + magazzino')}${kpi('Margine a oggi', chf(r.margine), pct(r.margPct), r.margine < 0 ? 'bad' : r.margPct < 12 ? 'warn' : 'good')}${kpi('CHF/ora realizzati', c.oreFatte ? chf(r.chfOra, 1) : '–', 'break-even ' + P.breakEvenOra, chfTone(r.chfOra))}</div>
  ${tabs('cant', [['redd', 'Redditività'], ['ore', 'Squadra e ore'], ['costi', 'Costi e fatture (' + forn.length + ')'], ['bol', 'Bollettini (' + bols.length + ')'], ['doc', 'Documenti, e-mail, calendario']])}${body}`;
}

// ---------- PIANIFICAZIONE ----------
function vPianificazione() {
  const start = addDays('2026-11-02', S.calWeek * 7); const days = [0, 1, 2, 3, 4].map((i) => addDays(start, i));
  const cs = DB.cantieri.filter((c) => ['In corso', 'Pianificato'].includes(c.stato));
  const ops = DB.workers.filter((w) => w.ramo !== 'U');
  const where = (w, d) => { const a = DB.assenze.find((x) => x.workerId === w.id && x.stato !== 'Rifiutata' && d >= x.dal && d <= x.al); if (a) return { abs: a }; return { c: cantiereDi(w.id, d) }; };
  const liberi = (d) => ops.filter((w) => { const x = where(w, d); return !x.abs && !x.c; });
  return `<div class="pagehead"><div><div class="eyebrow">Settimana ${fd(start)} – ${fd(days[4])}</div><h1>Pianificazione squadre</h1><p class="muted">Chi lavora dove, giorno per giorno. Clicca una casella per aggiungere o spostare persone; l'app degli operai e l'assistente car pooling si aggiornano.</p></div><div class="row"><button class="btn sm" data-act="cal-week" data-id="-1">‹ Settimana prec.</button><button class="btn sm" data-act="cal-week" data-id="0">Oggi</button><button class="btn sm" data-act="cal-week" data-id="1">Settimana succ. ›</button></div></div>
  <div class="planwrap"><div class="plan"><div class="ph">Cantiere</div>${days.map((d) => `<div class="ph ${d === D.TODAY_ISO ? 'today' : ''}">${dow[new Date(d + 'T12:00').getDay()]}<br><small>${fshort(d)}</small></div>`).join('')}
    ${cs.map((c) => `<div class="pr"><span class="num small muted">${c.id}</span><br>${esc(c.nome)}<br><span class="small muted">${esc(c.comune)} · ${c.kmDaBase} km</span></div>${days.map((d) => { const ppl = ops.filter((w) => { const x = where(w, d); return !x.abs && x.c && x.c.id === c.id; }); return `<div class="cell ${d === D.TODAY_ISO ? 'today' : ''}" data-act="plan-cell" data-id="${c.id}" data-day="${d}" title="${ppl.map((w) => w.nome).join(', ')}">${ppl.map((w) => `<span class="avatar xs ${avCls(w)}" title="${esc(w.nome)}">${initials(w.nome)}</span>`).join('')}${ppl.length ? `<span class="small muted" style="width:100%">${ppl.length} pers.</span>` : '<span class="small muted">–</span>'}</div>`; }).join('')}`).join('')}
    <div class="pr">Assenti</div>${days.map((d) => { const abs = ops.filter((w) => where(w, d).abs); return `<div class="cell">${abs.map((w) => `<span class="pill warn" title="${esc(w.nome)}">${initials(w.nome)} ${where(w, d).abs.tipo}</span>`).join('') || '<span class="small muted">–</span>'}</div>`; }).join('')}
    <div class="pr">Non pianificati</div>${days.map((d) => `<div class="cell">${liberi(d).map((w) => `<span class="avatar xs ${avCls(w)}" title="${esc(w.nome)}">${initials(w.nome)}</span>`).join('') || '<span class="small muted">nessuno</span>'}</div>`).join('')}
  </div></div>
  <div class="grid2"><div class="card"><h3>Assenze della settimana</h3>${DB.assenze.filter((a) => a.al >= start && a.dal <= days[4]).map((a) => `<div class="listrow"><span>${esc(worker(a.workerId).nome)} · ${a.tipo}<br><span class="small muted">${fd(a.dal)} – ${fd(a.al)} · ${a.giorni} gg</span></span>${pill(a.stato)}</div>`).join('') || '<p class="muted small">Nessuna</p>'}</div>
  <div class="card"><h3>Furgoni in partenza da Bioggio</h3>${DB.veicoli.filter((v) => v.assegnato && v.stato !== 'In officina').map((v) => { const w = worker(v.assegnato); const c = cantiereDi(w.id, D.TODAY_ISO); return `<div class="listrow"><span><span class="b num">${v.targa}</span> ${esc(v.modello)}<br><span class="small muted">${esc(w.nome)} → ${c ? esc(c.nome) : 'ufficio'}</span></span>${pill(v.stato)}</div>`; }).join('')}<button class="btn sm" style="margin-top:8px" data-act="nav" data-id="veicoli" data-tab="ia">${I('sparkles')} Proposte car pooling</button></div></div>`;
}

// ---------- BOLLETTINI ----------
function bolTable(list, actions = true, selKey) {
  return table([{ h: 'Data' }, { h: 'Collaboratore', cls: 'wrap' }, { h: 'Cantiere', cls: 'wrap' }, { h: 'Entrata–uscita' }, { h: 'Ore', cls: 'right num' }, { h: 'Viaggio', cls: 'right num' }, { h: 'Attività', cls: 'wrap' }, { h: 'GPS' }, { h: 'Stato' }, ...(actions ? [{ h: '' }] : [])],
    list.map((b) => { const w = worker(b.workerId); const c = cant(b.cantiere) || { id: b.cantiere, nome: '' }; return { id: b.id, c: [fshort(b.data), `<span class="b">${esc(w.nome)}</span><br><span class="small muted">${esc(w.ruolo)}</span>`, `<span class="num small">${c.id}</span><br>${esc(c.nome)}`, `<span class="num">${b.entrata}–${b.uscita}</span>`, `<span class="b">${n1(b.ore)}</span>`, n1(b.viaggio), esc(b.attivita) + (b.materiale ? `<br><span class="small muted">${esc(b.materiale)}</span>` : '') + (b.note ? `<br><span class="small" title="${esc(b.note)}">${b.vocale ? (I('mic') + ' ') : (I('edit') + ' ')}${esc(b.note.length > 60 ? b.note.slice(0, 58) + '…' : b.note)}</span>` : ''), b.gps > 100 ? `<span class="pill bad">▲ ${(b.gps / 1000).toFixed(1)} km</span>` : `<span class="pill good">✓ ${b.gps} m</span>`, pill(b.stato) + (b.anomalia ? `<br><span class="small" style="color:var(--warn)">${b.anomalia}</span>` : ''), ...(actions ? [b.stato === 'Inviato' ? `<span class="row nowrap"><button class="btn sm good" data-act="approve" data-id="${b.id}">Approva</button><button class="btn sm" data-act="reject" data-id="${b.id}">Rinvia</button></span>` : b.stato === 'Bozza' ? `<button class="btn sm" data-act="sollecita-bol" data-id="${b.id}">Sollecita</button>` : ''] : [])] }; }), { empty: 'Nessun bollettino in questo filtro', sel: selKey });
}
function vBollettini() {
  const tb = curTab('bol', 'coda'); const f = S.filtroBol;
  const list = DB.bollettini.filter((b) => f === 'da-approvare' ? b.stato === 'Inviato' : f === 'anomalie' ? b.anomalia : f === 'bozze' ? b.stato === 'Bozza' : f === 'vocali' ? b.vocale : true).sort((a, b) => b.data.localeCompare(a.data));
  const daApp = DB.bollettini.filter((b) => b.stato === 'Inviato').length;
  let body = '';
  if (tb === 'coda') body = `<div class="row between">${chips('filtro-bol', f, [['da-approvare', 'Da approvare (' + daApp + ')'], ['anomalie', 'Con anomalia'], ['vocali', I('mic') + ' Con nota vocale'], ['bozze', 'Bozze non inviate'], ['tutti', 'Tutti (2 settimane)']])}<div class="row"><button class="btn" data-act="export-csv" data-id="bollettini">${I('download')} Esporta</button><button class="btn primary" data-act="approve-all" ${daApp ? '' : 'disabled'}>Approva tutti senza anomalie</button></div></div>
    ${selbar('bol', null, [{ label: '✓ Approva selezionati', act: 'bulk-approve' }, { label: I('reply') + ' Rinvia selezionati', act: 'bulk-reject' }])}<div class="card pad0">${bolTable(list, true, 'bol')}</div>`;
  if (tb === 'cong') body = vConguaglio();
  if (tb === 'ass') body = vAssenze();
  return `<div class="pagehead"><div><div class="eyebrow">Controllo ore</div><h1>Bollettini</h1><p class="muted">Gli operai timbrano e compilano dall'app, anche a voce; qui Stefano e Antonio controllano in tempo reale, non più a fine settimana.</p></div></div>
  ${tabs('bol', [['coda', 'Coda di approvazione'], ['cong', 'Conguaglio mensile ottobre'], ['ass', 'Assenze e vacanze (' + DB.assenze.filter((a) => a.stato === 'Richiesta').length + ')']])}${body}`;
}
function vConguaglio() {
  const ops = DB.workers.filter((w) => w.ramo !== 'U');
  const rows = ops.map((w, i) => {
    const contr = 22 * 8; const eff = 176 + ((i * 7) % 23) - 11 - ((i % 5) * 8); const vac = (i % 4 === 0) ? 1 : 0; const mal = (i % 9 === 0) ? 2 : 0;
    const straord = Math.max(eff + vac * 8 + mal * 8 - contr, 0); const c = cantiereDi(w.id); const ip = indennitaPranzo(w, c);
    const pranzo = w.ramo === 'G' ? P.pranzoGessatoriMese : ip.val * (eff / 8 | 0);
    const km = DB.kmPrivati.filter((k) => k.workerId === w.id).reduce((a, k) => a + k.km, 0) * 3;
    const salario = w.salario + straord * (w.salario * 13 / P.oreAnnue) * (1 + P.straordinarioPct / 100) + pranzo + km * P.kmTariffa;
    return { id: w.id, act: 'open-worker', cls: 'click', c: [`<span class="b">${esc(w.nome)}</span><br><span class="small muted">${esc(w.ruolo)}</span>`, n0(contr), `<span class="b">${n0(eff)}</span>`, vac || '–', mal || '–', straord ? `<span class="b" style="color:var(--warn)">+${n0(straord)}</span>` : '–', pranzo ? chf(pranzo) : '–', km ? `${n0(km)} km · ${chf(km * P.kmTariffa)}` : '–', `<span class="b">${chf(salario)}</span>`, i % 6 === 0 ? `<span class="pill warn">Manca 1 bollettino</span>` : `<span class="pill good">Completo</span>`] };
  });
  return `<div class="alert info"><span>${I('info')}</span><span>Stipendio mensile su base oraria: tutti i bollettini di ottobre vanno chiusi entro il 5 novembre. Il conguaglio somma ore effettive, straordinari (+${P.straordinarioPct}%), vacanze, indennità pranzo e km, e passa a SelectLine salari.</span></div>
  ${selbar('cong', null, [{ label: 'Esporta selezionati a SelectLine Lohn', act: 'toast-sel', id: 'Conguaglio esportato a SelectLine Lohn per i collaboratori selezionati' }, { label: 'Invia riepilogo PDF', act: 'toast-sel', id: 'Riepilogo ore inviato sull\'app ai collaboratori selezionati' }])}
  <div class="card pad0">${table([{ h: 'Collaboratore', cls: 'wrap' }, { h: 'Ore contratto', cls: 'right num' }, { h: 'Ore effettive', cls: 'right num' }, { h: 'Vacanze gg', cls: 'right num' }, { h: 'Malattia gg', cls: 'right num' }, { h: 'Straord.', cls: 'right num' }, { h: 'Pranzo', cls: 'right num' }, { h: 'Km privati', cls: 'right num' }, { h: 'Lordo stimato', cls: 'right num' }, { h: 'Bollettini' }], rows, { sel: 'cong' })}</div>
  <div class="row"><button class="btn primary" data-act="toast" data-msg="Conguaglio ottobre esportato a SelectLine Lohn (36 collaboratori)">Esporta conguaglio a SelectLine</button><button class="btn" data-act="toast" data-msg="PDF riepilogo ore inviato a ogni collaboratore sull'app">Invia riepiloghi agli operai</button><button class="btn" data-act="export-csv" data-id="conguaglio">${I('download')} Esporta Excel</button></div>`;
}
function vAssenze() {
  return `<div class="row between"><p class="muted small">Richieste dall'app operaio: vacanze, malattia con certificato fotografato, scuola professionale. Approvando, la pianificazione si aggiorna e il saldo vacanze scala.</p><button class="btn primary" data-act="new-entity" data-ent="assenza">+ Nuova assenza</button></div>
  ${selbar('ass', 'assenza', [{ label: '✓ Approva selezionate', act: 'bulk-approve-ass' }])}
  <div class="card pad0">${table([{ h: 'Collaboratore', cls: 'wrap' }, { h: 'Tipo' }, { h: 'Dal' }, { h: 'Al' }, { h: 'Giorni', cls: 'right num' }, { h: 'Nota', cls: 'wrap' }, { h: 'Saldo vacanze', cls: 'right num' }, { h: 'Stato' }, { h: '' }], DB.assenze.map((a) => { const w = worker(a.workerId); return { id: a.id, c: [`<span class="b">${esc(w.nome)}</span><br><span class="small muted">${esc(w.ruolo)}</span>`, a.tipo, fd(a.dal), fd(a.al), a.giorni, esc(a.nota || '–'), (w.vacanzeTot - w.vacanzeUsate) + ' gg', pill(a.stato), a.stato === 'Richiesta' ? `<span class="row nowrap"><button class="btn sm good" data-act="ass-ok" data-id="${a.id}">Approva</button><button class="btn sm" data-act="ass-no" data-id="${a.id}">Rifiuta</button></span>` : `<button class="btn sm ghost" data-act="edit-entity" data-ent="assenza" data-id="${a.id}">${I('edit')}</button>`] }; }), { sel: 'ass' })}</div>`;
}

// ---------- PERSONE: collaboratori, clienti, fornitori ----------
function vPersone() {
  const tb = curTab('persone', 'coll');
  let body = '';
  if (tb === 'coll') body = vTeam();
  if (tb === 'cli') body = vClienti();
  if (tb === 'forn') body = vFornitori();
  return `<div class="pagehead"><div><div class="eyebrow">Anagrafiche</div><h1>Persone</h1></div></div>
  ${subtabs('persone', [['coll', I('user') + ' Collaboratori (' + DB.workers.length + ')'], ['cli', I('phone') + ' Clienti (' + DB.clienti.length + ')'], ['forn', I('factory') + ' Fornitori (' + DB.fornitori.length + ')']])}${body}`;
}
function vTeam() {
  const f = S.filtroTeam;
  const list = DB.workers.filter((w) => f === 'tutti' ? true : f === 'G' ? w.ramo === 'G' : f === 'P' ? w.ramo === 'P' : f === 'U' ? w.ramo === 'U' : f === 'app' ? w.app !== 'Attivo' : true);
  const cnt = (r) => DB.workers.filter((w) => w.ramo === r).length;
  return `<div class="row between"><div><p class="muted">${DB.workers.length} persone: ${cnt('G')} gessatori, ${cnt('P')} pittori, ${cnt('U')} in ufficio. Tariffe da CCL pittura e gessatura 2026.</p></div><div class="row"><button class="btn" data-act="export-csv" data-id="team">${I('download')} Esporta</button><button class="btn" data-act="invite-open">Invita sull'app</button><button class="btn primary" data-act="new-entity" data-ent="worker">+ Nuovo collaboratore</button></div></div>
  ${chips('filtro-team', f, [['tutti', 'Tutti'], ['G', 'Gessatori'], ['P', 'Pittori'], ['U', 'Ufficio'], ['app', 'Senza accesso app']])}
  ${selbar('team', 'worker', [{ label: I('message') + ' Messaggio', act: 'bulk-msg' }, { label: 'Assegna a cantiere', act: 'bulk-assign' }])}
  <div class="card pad0">${table([{ h: 'Collaboratore', cls: 'wrap' }, { h: 'Ruolo / CCL' }, { h: 'Competenze', cls: 'wrap' }, { h: 'Esperienza', cls: 'right num' }, { h: 'Residenza' }, { h: 'Costo az./h', cls: 'right num' }, { h: 'Cantiere attuale', cls: 'wrap' }, { h: 'Vacanze' }, { h: 'App' }],
    list.map((w) => { const c = cantiereDi(w.id); return { act: 'open-worker', id: w.id, cls: 'click', c: [`<span class="row nowrap">${avatar(w.nome, avCls(w))}<span><span class="b">${esc(w.nome)}</span><br><span class="small muted">${esc(w.tel)}</span></span></span>`, `${esc(w.ruolo)}<br><span class="small muted">${D.CCL[w.cat] ? 'Cat. ' + w.cat + ' · ' + D.CCL[w.cat].label : 'Quadro'}</span>`, w.competenze.map((k) => `<span class="chip">${esc(k)}</span>`).join(''), w.anni + ' anni', `${esc(w.residenza)}${w.frontaliere ? ' <span class="pill">frontaliere</span>' : ''}<br><span class="small muted">${w.kmDaBase} km dalla base</span>`, w.ramo === 'U' ? '–' : chf(w.costoAziendaOra, 2), c ? `<span class="num small">${c.id}</span><br>${esc(c.nome)}` : '<span class="muted">–</span>', w.ramo === 'U' ? '–' : `${w.vacanzeTot - w.vacanzeUsate} / ${w.vacanzeTot} gg`, pill(w.app || 'Attivo')] }; }), { sel: 'team' })}</div>`;
}
function vClienti() {
  const q = (S.sel.qCli || '').toLowerCase(); const list = DB.clienti.filter((k) => !q || k.nome.toLowerCase().includes(q) || k.comune.toLowerCase().includes(q) || k.contatto.toLowerCase().includes(q));
  const vol = (k) => DB.cantieri.filter((c) => c.clienteId === k.id).reduce((a, c) => a + (c.deliberato || 0), 0);
  const aperto = (k) => DB.fatture.filter((f) => f.clienteId === k.id && ['Inviata', 'Scaduta'].includes(f.stato)).reduce((a, f) => a + f.importo, 0);
  return `<div class="row between"><input placeholder="Filtra clienti…" value="${esc(S.sel.qCli || '')}" data-act-input="qCli" style="max-width:280px"><div class="row"><button class="btn" data-act="export-csv" data-id="clienti">${I('download')} Esporta</button><button class="btn primary" data-act="new-entity" data-ent="cliente">+ Nuovo cliente</button></div></div>
  ${selbar('clienti', 'cliente', [{ label: I('mail') + ' E-mail a tutti', act: 'bulk-mail' }])}
  <div class="card pad0">${table([{ h: 'Cliente', cls: 'wrap' }, { h: 'Tipo' }, { h: 'Contatto', cls: 'wrap' }, { h: 'Comune' }, { h: 'Cantieri', cls: 'right num' }, { h: 'Volume deliberato', cls: 'right num' }, { h: 'Aperto', cls: 'right num' }, { h: 'Ultimo contatto' }],
    list.map((k) => ({ act: 'open-cliente', id: k.id, cls: 'click', c: [`<span class="b">${esc(k.nome)}</span><br><span class="small muted">${esc(k.email)}</span>`, `<span class="pill">${esc(k.tipo)}</span>`, `${esc(k.contatto)}<br><span class="small muted num">${esc(k.tel)}</span>`, esc(k.comune), DB.cantieri.filter((c) => c.clienteId === k.id).length, chf(vol(k)), aperto(k) ? `<span class="b" style="color:${DB.fatture.some((f) => f.clienteId === k.id && f.stato === 'Scaduta') ? 'var(--bad)' : 'inherit'}">${chf(aperto(k))}</span>` : '–', fd(k.ultimoContatto)] })), { sel: 'clienti' })}</div>`;
}
function vFornitori() {
  const spesa = (f) => DB.fattForn.filter((x) => x.fornitoreId === f.id).reduce((a, x) => a + x.importo, 0);
  const aperto = (f) => DB.fattForn.filter((x) => x.fornitoreId === f.id && x.stato !== 'Esportata SelectLine').reduce((a, x) => a + x.importo, 0);
  return `<div class="row between"><p class="muted small">Anagrafica fornitori con categoria di costo, condizioni, fatture, ordini, e-mail e appuntamenti sincronizzati da Outlook.</p><div class="row"><button class="btn" data-act="export-csv" data-id="fornitori">${I('download')} Esporta</button><button class="btn primary" data-act="new-entity" data-ent="fornitore">+ Nuovo fornitore</button></div></div>
  ${selbar('fornitori', 'fornitore', [{ label: I('mail') + ' E-mail a tutti', act: 'bulk-mail' }])}
  <div class="card pad0">${table([{ h: 'Fornitore', cls: 'wrap' }, { h: 'Categoria' }, { h: 'Contatto', cls: 'wrap' }, { h: 'Condizioni' }, { h: 'Sconto', cls: 'right num' }, { h: 'Fatture 2026', cls: 'right num' }, { h: 'Da esportare', cls: 'right num' }],
    DB.fornitori.map((f) => ({ act: 'open-fornitore', id: f.id, cls: 'click', c: [`<span class="b">${esc(f.nome)}</span><br><span class="small muted">${esc(f.comune)} · ${esc(f.email)}</span>`, `<span class="pill">${esc(f.categoria)}</span>`, `${esc(f.contatto)}<br><span class="small muted num">${esc(f.tel)}</span>`, esc(f.pagamento), f.sconto ? pct(f.sconto) : '–', chf(spesa(f)), aperto(f) ? chf(aperto(f)) : '–'] })), { sel: 'fornitori' })}</div>`;
}

function relPage(kind, obj) {
  const rel = { t: kind, id: obj.id }; const tb = curTab(kind, 'pan');
  const em = DB.email.filter((e) => e.rel && e.rel.t === kind && e.rel.id === obj.id).sort((a, b) => b.data.localeCompare(a.data));
  const ev = DB.eventi.filter((e) => e.rel && e.rel.t === kind && e.rel.id === obj.id).sort((a, b) => a.inizio.localeCompare(b.inizio));
  const att = DB.attivita.filter((a) => a.rel && a.rel.t === kind && a.rel.id === obj.id).sort((a, b) => (a.done - b.done) || b.data.localeCompare(a.data));
  const isC = kind === 'cliente';
  const cants = isC ? DB.cantieri.filter((c) => c.clienteId === obj.id) : [];
  const offs = isC ? DB.offerte.filter((o) => o.clienteId === obj.id) : [];
  const fatt = isC ? DB.fatture.filter((f) => f.clienteId === obj.id) : DB.fattForn.filter((f) => f.fornitoreId === obj.id);
  const ord = isC ? [] : DB.ordini.filter((o) => o.fornitoreId === obj.id);
  const caps = isC ? DB.capitolati.filter((c) => c.clienteId === obj.id) : [];
  const tot = isC ? cants.reduce((a, c) => a + (c.deliberato || 0), 0) : fatt.reduce((a, f) => a + f.importo, 0);
  const aperto = fatt.filter((f) => isC ? ['Inviata', 'Scaduta'].includes(f.stato) : f.stato !== 'Esportata SelectLine').reduce((a, f) => a + f.importo, 0);
  const pre = esc(JSON.stringify({ relKey: kind + '|' + obj.id }));
  let body = '';
  if (tb === 'pan') body = `<div class="grid2"><div class="card"><h3>Anagrafica</h3><dl class="dl"><dt>Contatto</dt><dd>${esc(obj.contatto)}</dd><dt>E-mail</dt><dd><button class="btn sm ghost" data-act="compose-to" data-rel="${kind}|${obj.id}" style="padding:0">${esc(obj.email)}</button></dd><dt>Telefono</dt><dd class="num">${esc(obj.tel)}</dd><dt>Indirizzo</dt><dd>${esc(obj.indirizzo || '')} ${esc(obj.comune)}</dd><dt>Pagamento</dt><dd>${esc(obj.pagamento || '30 giorni')}</dd>${isC ? '' : `<dt>Categoria</dt><dd>${esc(obj.categoria)}</dd><dt>Sconto</dt><dd>${obj.sconto ? pct(obj.sconto) : '–'}</dd><dt>IBAN</dt><dd class="num">${esc(obj.iban || '–')}</dd>`}<dt>Note</dt><dd>${esc(obj.note || '–')}</dd><dt>SharePoint</dt><dd><button class="btn sm ghost" data-act="toast" data-msg="Apre SharePoint/${esc(obj.sharepoint)}" style="padding:0">${I('file')} ${esc(obj.sharepoint)}</button></dd></dl>
    ${isC ? `<div class="eyebrow" style="margin-top:12px">Persone di contatto</div>${(obj.contatti || []).map((p, i) => `<div class="listrow"><span><span class="b">${esc(p.nome)}</span> <span class="small muted">· ${esc(p.ruolo)}</span><br><span class="small muted">${esc(p.email)} · ${esc(p.tel)}</span></span><span class="row nowrap"><button class="btn sm" data-act="compose-to" data-rel="${kind}|${obj.id}" data-to="${esc(p.email)}" data-contatto="${esc(p.nome)}">${I('mail')}</button><button class="btn sm ghost" data-act="edit-contatto" data-id="${obj.id}|${i}">${I('edit')}</button></span></div>`).join('')}<button class="btn sm" style="margin-top:8px" data-act="new-contatto" data-id="${obj.id}">+ Contatto</button>` : ''}</div>
    <div class="stack"><div class="card"><div class="row between"><h3>Attività (chiamate, promemoria, note)</h3><button class="btn sm primary" data-act="new-entity" data-ent="attivita" data-prefill='${pre}'>+ Attività</button></div>${activityList(att)}</div>
    <div class="card"><h3>${isC ? 'Cantieri, offerte e capitolati' : 'Ordini'}</h3>${isC ? (cants.map((c) => `<div class="listrow click" data-act="open-cantiere" data-id="${c.id}"><span><span class="small num muted">${c.id}</span><br><span class="b">${esc(c.nome)}</span> <span class="small muted">· margine ${pct(calc(c).margPct)}</span></span>${pill(c.stato)}</div>`).join('') + offs.filter((o) => !o.cantiere).map((o) => `<div class="listrow click" data-act="open-offerta" data-id="${o.id}"><span><span class="small num muted">${o.id}</span><br><span class="b">${esc(o.oggetto)}</span></span>${pill(o.stato)}</div>`).join('') + caps.map((cp) => `<div class="listrow click" data-act="open-capitolato" data-id="${cp.id}"><span>${I('file-text')} ${esc(cp.titolo)}<br><span class="small muted">${cp.domande.filter((d) => d.stato === 'Aperta').length} domande aperte</span></span>${pill(cp.stato)}</div>`).join('') || '<p class="muted small">Nessun cantiere</p>') : (ord.map((o) => `<div class="listrow"><span><span class="small num muted">${o.id} · ${fd(o.data)}</span><br>${esc(o.articoli)}</span><span class="row nowrap"><span class="b num">${chf(o.importo)}</span>${pill(o.stato)}</span></div>`).join('') || '<p class="muted small">Nessun ordine</p>') + `<button class="btn sm" style="margin-top:8px" data-act="new-entity" data-ent="ordine" data-prefill='${esc(JSON.stringify({ fornitoreId: obj.id }))}'>+ Ordine</button>`}</div></div></div>`;
  if (tb === 'mail') body = `<div class="card"><div class="row between"><h3>Outlook · ${em.length} e-mail sincronizzate</h3><button class="btn primary sm" data-act="compose-to" data-rel="${kind}|${obj.id}">${I('mail')} Nuova e-mail</button></div>${emailList(em)}<p class="small muted" style="margin-top:10px">Le e-mail con ${esc(obj.email)} vengono associate in automatico alla scheda tramite Microsoft Graph; da qui si risponde e si inviano offerte, fatture e solleciti.</p></div>`;
  if (tb === 'cal') body = `<div class="card"><div class="row between"><h3>Calendario · appuntamenti con ${esc(obj.nome)}</h3><button class="btn primary sm" data-act="new-entity" data-ent="evento" data-prefill='${esc(JSON.stringify({ relKey: kind + '|' + obj.id, titolo: (isC ? 'Sopralluogo ' : 'Incontro ') + obj.nome, tipo: isC ? 'Sopralluogo' : 'Riunione', luogo: obj.comune }))}'>+ Appuntamento</button></div>${eventList(ev)}<p class="small muted" style="margin-top:10px">Gli appuntamenti sono nel calendario Outlook di chi partecipa e qui nella scheda.</p></div>`;
  if (tb === 'fat') body = isC
    ? `${selbar('cli-fat', 'fattura', [{ label: 'Segna pagate', act: 'bulk-paid' }, { label: I('mail') + ' Sollecita', act: 'bulk-sollecito' }])}<div class="card pad0">${fattureTable(fatt, 'cli-fat')}</div><div class="row"><button class="btn primary" data-act="fwiz-open" data-id="${(offs.find((o) => o.stato === 'Deliberata') || {}).id || ''}">+ Fattura da offerta</button><button class="btn" data-act="new-entity" data-ent="fattura" data-prefill='${esc(JSON.stringify({ clienteId: obj.id, tipo: 'Regia', data: D.TODAY_ISO, scadenza: addDays(D.TODAY_ISO, 30), stato: 'Bozza' }))}'>+ Fattura a regia</button></div>`
    : `${selbar('forn-fat', 'fatturaForn', [{ label: 'Esporta a SelectLine', act: 'bulk-export-ff' }])}<div class="card pad0">${table([{ h: 'Fattura' }, { h: 'Cantiere', cls: 'wrap' }, { h: 'Categoria' }, { h: 'Data' }, { h: 'Scadenza' }, { h: 'Importo', cls: 'right num' }, { h: 'Stato' }, { h: '' }], fatt.map((f) => ({ id: f.id, c: [`<span class="b num">${f.id}</span>${f.allegato ? `<br><span class="small muted">${I('attach')} ${esc(f.allegato)}</span>` : ''}`, f.cantiere ? `<span class="num small">${f.cantiere}</span><br>${esc((cant(f.cantiere) || {}).nome || '')}` : '<span class="pill bad">da assegnare</span>', `<span class="pill">${esc(f.categoria)}</span>`, fd(f.data), fd(f.scadenza), chf(f.importo, 2), pill(f.stato), `<button class="btn sm ghost" data-act="edit-entity" data-ent="fatturaForn" data-id="${f.id}">${I('edit')}</button>`] })), { sel: 'forn-fat' })}</div><div class="row"><button class="btn primary" data-act="ocr-open">${I('camera')} Carica fattura</button><button class="btn" data-act="new-entity" data-ent="fatturaForn" data-prefill='${esc(JSON.stringify({ fornitoreId: obj.id, categoria: obj.categoria, data: D.TODAY_ISO, scadenza: addDays(D.TODAY_ISO, 30), stato: 'Registrata' }))}'>+ Inserisci a mano</button></div>`;
  return `<div class="row small"><button class="btn sm" data-act="nav" data-id="persone" data-tab="${isC ? 'cli' : 'forn'}">${I('back')} ${isC ? 'Clienti' : 'Fornitori'}</button></div>
  <div class="pagehead"><div><div class="eyebrow">${isC ? obj.tipo : obj.categoria}</div><h1>${esc(obj.nome)}</h1><p class="muted">${esc(obj.contatto)} · ${esc(obj.comune)} · ultimo contatto ${fd(isC ? obj.ultimoContatto : (em[0] || {}).data || D.TODAY_ISO)}</p></div><div class="row"><button class="btn primary" data-act="compose-to" data-rel="${kind}|${obj.id}">${I('mail')} E-mail</button><button class="btn" data-act="toast" data-msg="Chiamata Teams a ${esc(obj.contatto)} (${esc(obj.tel)})">${I('phone')} Chiama</button><button class="btn" data-act="new-entity" data-ent="attivita" data-prefill='${esc(JSON.stringify({ relKey: kind + '|' + obj.id, tipo: 'Promemoria', data: addDays(D.TODAY_ISO, 1), ora: '09:00' }))}'>${I('alarm')} Promemoria</button><button class="btn" data-act="edit-entity" data-ent="${kind}" data-id="${obj.id}">${I('edit')} Modifica</button></div></div>
  <div class="kpis">${kpi(isC ? 'Volume deliberato' : 'Acquisti 2026', chf(tot))}${kpi(isC ? 'Fatture aperte' : 'Da esportare', chf(aperto), fatt.length + ' fatture', aperto && isC && fatt.some((f) => f.stato === 'Scaduta') ? 'bad' : '')}${kpi('E-mail', em.length, em.filter((e) => e.unread).length + ' da leggere')}${kpi('Attività aperte', att.filter((a) => !a.done).length, 'prossima: ' + (att.find((a) => !a.done) ? fd(att.find((a) => !a.done).data) : '–'))}</div>
  ${tabs(kind, [['pan', 'Panoramica e attività'], ['mail', I('mail') + ' E-mail (' + em.length + ')'], ['cal', I('calendar') + ' Calendario (' + ev.length + ')'], ['fat', isC ? 'Fatture (' + fatt.length + ')' : 'Fatture e ordini (' + fatt.length + ')']])}${body}`;
}
function vCliente() { const k = cliente(S.id); if (!DB.clienti.includes(k)) { S.tab.persone = 'cli'; return vPersone(); } return relPage('cliente', k); }
function vFornitore() { const f = fornitore(S.id); if (!DB.fornitori.includes(f)) { S.tab.persone = 'forn'; return vPersone(); } return relPage('fornitore', f); }
